            m = len(routes)
            for i in range(m):
                ri = routes[i]
                if len(ri) <= 1:
                    continue
                for pos in range(len(ri)):
                    cust = ri[pos]
                    best = None  # (delta, j, ins, new_ri, new_rj)
                    for j in range(m):
                        if j == i:
                            continue
                        if loads[j] + demands[cust] > capacity:
                            continue
                        rj = routes[j]
                        new_ri = ri[:pos] + ri[pos + 1:]
                        base = costs[i] + costs[j]
                        # try insertion positions
                        for ins in range(len(rj) + 1):
                            if ins == 0:
                                new_rj = [cust] + rj
                            elif ins == len(rj):
                                new_rj = rj + [cust]
                            else:
                                new_rj = rj[:ins] + [cust] + rj[ins:]
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = base - new_cost
                            if delta > 1e-9:
                                if best is None or delta > best[0]:
                                    best = (delta, j, ins, new_ri, new_rj)
                    if best is not None:
                        delta, j, ins, new_ri, new_rj = best
                        routes[i] = new_ri
                        routes[j] = new_rj
                        loads[i] -= demands[cust]
                        loads[j] += demands[cust]
                        costs[i] = route_cost(new_ri)
                        costs[j] = route_cost(new_rj)
                        improved_any = True
                        if not routes[i]:
                            routes.pop(i)
                        break
                if improved_any:
                    break
            if not improved_any:
                break

    relocate_phase()

    # 4) New small edit: inter-route exchange (swap one customer) to reduce gap further
    def exchange_phase():
        nonlocal routes
        for _ in range(4):
            improved_any = False
            m = len(routes)
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]

            for i in range(m):
                if i >= len(routes):
                    break
                ri = routes[i]
                if not ri:
                    continue
                # deterministic candidate positions: boundaries first
                cand_pos_i = []
                if len(ri) >= 1:
                    cand_pos_i.append(0)
                    if len(ri) - 1 != 0:
                        cand_pos_i.append(len(ri) - 1)
                    if len(ri) >= 3:
                        cand_pos_i.append(1)
                        if len(ri) - 2 != 1:
                            cand_pos_i.append(len(ri) - 2)

                for j in range(i + 1, m):
                    if j >= len(routes) or i >= len(routes):
                        break
                    rj = routes[j]
                    if not rj:
                        continue
                    cand_pos_j = []
                    if len(rj) >= 1:
                        cand_pos_j.append(0)
                        if len(rj) - 1 != 0:
                            cand_pos_j.append(len(rj) - 1)
                        if len(rj) >= 3:
                            cand_pos_j.append(1)
                            if len(rj) - 2 != 1:
                                cand_pos_j.append(len(rj) - 2)

                    best = None  # (delta, pi, pj, new_ri, new_rj)
                    base = costs[i] + costs[j]
                    for pi in cand_pos_i:
                        if pi >= len(ri):
                            continue
                        a = ri[pi]
                        for pj in cand_pos_j:
                            if pj >= len(rj):
                                continue
                            b = rj[pj]
                            # feasibility check
                            new_load_i = loads[i] - demands[a] + demands[b]
                            new_load_j = loads[j] - demands[b] + demands[a]
                            if new_load_i > capacity or new_load_j > capacity:
                                continue
                            if a == b:
                                continue
                            new_ri = ri[:pi] + [b] + ri[pi + 1:]
                            new_rj = rj[:pj] + [a] + rj[pj + 1:]
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = base - new_cost
                            if delta > 1e-9:
                                if best is None or delta > best[0] or (delta == best[0] and (pi, pj) < (best[1], best[2])):
                                    best = (delta, pi, pj, new_ri, new_rj)

                    if best is not None:
                        _, pi, pj, new_ri, new_rj = best
                        routes[i] = new_ri
                        routes[j] = new_rj
                        loads[i] = route_load(new_ri)
                        loads[j] = route_load(new_rj)
                        costs[i] = route_cost(new_ri)
                        costs[j] = route_cost(new_rj)
                        routes[i] = two_opt_intra(routes[i])
                        routes[j] = two_opt_intra(routes[j])
                        loads[i] = route_load(routes[i])
                        loads[j] = route_load(routes[j])
                        costs[i] = route_cost(routes[i])
                        costs[j] = route_cost(routes[j])
                        improved_any = True
                        break

                if improved_any:
                    break

            if not improved_any:
                break

    exchange_phase()

    # Final cleanup
    routes = [r for r in routes if r]
    return routes
